import{z as B,x as A,o as E,c as l,q as r,j as t,D as a,d as o,s as i,S as s}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"效用函数何时存在","description":"","frontmatter":{"title":"效用函数何时存在","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/utility-representation.md","filePath":"econ/utility-representation.md","lastUpdated":1791413859000}'),u={name:"econ/utility-representation.md"};function p(c,e,m,d,D,h){const n=A("Mermaid");return E(),l("div",null,[e[2]||(e[2]=r('<h1 id="效用函数何时存在" tabindex="-1">效用函数何时存在 <a class="header-anchor" href="#效用函数何时存在" aria-label="Permalink to &quot;效用函数何时存在&quot;">​</a></h1><div class="epigraph"><p>一个连续的效用函数表示一个连续的偏好；反过来，连续偏好在适当的消费集上总可以被连续函数表示。</p><footer>—— 据 Debreu, Representation of a preference ordering by a numerical function, 1954；Theory of Value, 1959 整理</footer></div><p><a href="/econ/convex-preference">上一课</a>（凸偏好）。在此之上，理性偏好钉死：完备加传递，有限菜单上最大元非空。本课不重讲这两条公理，也不从「幸福」另起炉灶。缺口是：排序还只是二元关系，后课的预算最大化、斯勒茨基分解都要在实函数上做微分。何时存在 \\(u:X\\to\\mathbb{R}\\)，使 \\(u(x)\\ge u(y)\\) 当且仅当 \\(x\\succsim y\\)？后课默认已经读完本课，见到 \\(u\\) 就把它读成这个表示，而不是心理强度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限集上，理性本身就够。把最大元标成 \\(n\\)，次大标成 \\(n-1\\)，一直标下去，得到的是序数效用：任何严格递增变换 \\(f\\circ u\\) 表示同一套 \\(\\succsim\\)。缺口出在消费理论真正用的 \\(X\\subseteq\\mathbb{R}_+^n\\)。这里菜单可以是闭集、无界集，最大元可能不存在；即便存在，也不保证能用<strong>连续</strong>函数把整条关系写下来。不连续的表示会让后课的需求对应在价格上跳来跳去，包络定理没有对象。</p><p>因此本课要加的不是新的「喜欢」，而是拓扑条件：偏好在 \\(X\\) 的序拓扑里连续——上优集 \\(\\{y:y\\succsim x\\}\\) 与下优集 \\(\\{y:x\\succsim y\\}\\) 都闭。Debreu 的表示定理说：在连通的消费集上，连续的理性偏好有连续效用表示。单调与凸已经在上一课之前钉过；本课用它们只是为了后课的内部解更稳，不是再引入公理。</p><h3 id="表示是序数的-数字没有基数含义" tabindex="-1">表示是序数的，数字没有基数含义 <a class="header-anchor" href="#表示是序数的-数字没有基数含义" aria-label="Permalink to &quot;表示是序数的，数字没有基数含义&quot;">​</a></h3><p>\\(u(x)=2\\)、\\(u(y)=1\\) 只说 \\(x\\) 至少与 \\(y\\) 一样好，不说「好一倍」。后课写 \\(\\max u(x)\\) 时，一阶条件里的 \\(\\nabla u\\) 会随单调变换改尺度，但切点本身不变。人际比较同样读不出来：两个人的 \\(u\\) 不能相加。那是<a href="/econ/welfare-theorems">福利定理</a>另引进的公理，不是本课的副产品。</p><p><span class="marginnote">无差异曲线是 \\(u\\) 的水平集。有了连续 \\(u\\)，才谈得上「曲线」。上一课只有无差异关系，没有拓扑，画不出图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取 \\(X\\subseteq\\mathbb{R}_+^n\\) 连通（常用凸锥或非负象限）。理性且连续的 \\(\\succsim\\) 对应某个连续 \\(u\\)。构造不必唯一：Debreu 的证明用开区间去嵌偏好的分划；教科书里更常见的是沿一条严格单调路径取「刚好无差异」的标量。本课不把证明展开成习题，只锁定三件事：存在、连续、序数。</p><p>有了 \\(u\\)，菜单 \\(B\\) 上的最大元改写成 \\(\\arg\\max_{x\\in B}u(x)\\)。有限 \\(B\\) 上这与上一课的最大元相同；闭有界 \\(B\\) 上 Weierstrass 保证非空。预算集是后课才引进的特殊 \\(B\\)，本课不写价格。</p>',12)),(E(),t(s,null,{default:a(()=>[i(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E7%90%86%E6%80%A7%E5%81%8F%E5%A5%BD%20%E2%89%BD%22%5D%20--%3E%20C%5B%22%E8%BF%9E%E7%BB%AD%E6%80%A7%EF%BC%9A%E4%B8%8A%E4%B8%8B%E4%BC%98%E9%9B%86%E4%B8%BA%E9%97%AD%22%5D%0A%20%20C%20--%3E%20U%5B%22%E8%BF%9E%E7%BB%AD%E6%95%88%E7%94%A8%E8%A1%A8%E7%A4%BA%20u%22%5D%0A%20%20U%20--%3E%20M%5B%22argmax%20u%20%E4%BA%8E%E8%8F%9C%E5%8D%95%20B%22%5D%0A%20%20M%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A2%84%E7%AE%97%E4%B8%8E%E9%A9%AC%E6%AD%87%E5%B0%94%E9%9C%80%E6%B1%82%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<p>凸性已经在<a href="/econ/convex-preference">凸偏好</a>进场。无差异集可以向原点弯；表示定理本身不管这个，但后课严格凸才让马歇尔需求单值。单调性同样已经有了：它可以保证内部解，但不创造 \\(u\\)。可微更后：Debreu 只给连续函数，导数是为了写斯勒茨基才另加的光滑。</p><p>局部非餍足已在<a href="/econ/monotonicity-lns">单调与局部非饱和</a>钉过。本课只保证「排序能写成函数」；钱是否花完，是需求课拿去用的，不是表示定理的结论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续性排除「无穷小跳跃」：若 \\(x^n\\to x\\) 且每一点都优于 \\(y\\)，极限不能突然劣于 \\(y\\)。这让无差异集把 \\(X\\) 分成整齐的层，效用沿着层递增。后课对价格求导，靠的就是这层结构可微或至少局部 Lipschitz——可微是额外光滑，不是表示定理的结论。</p><p>序数性意味着后课所有「效用差」的说法都要翻译回偏好。马歇尔需求在单调变换下不变，间接效用会变，但间接效用的最大化者不变。这就是为什么需求课可以随便选一个方便的 \\(u\\)（拟线性、Cobb–Douglas），只要它表示同一 \\(\\succsim\\)。</p><p><span class="marginnote">词典序是理性但不连续的标准反例：它没有连续效用表示。后课默认不把词典序当消费者。</span></p>',6)),(E(),t(s,null,{default:a(()=>[i(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20XN%5B%22%E4%B8%80%E5%88%97%E5%95%86%E5%93%81%E6%9D%9F%20x%5En%20%E6%94%B6%E6%95%9B%E5%88%B0%20x%22%5D%20--%3E%20Q%7B%22%E8%BF%9E%E7%BB%AD%E6%80%A7%E6%A3%80%E9%AA%8C%22%7D%0A%20%20Q%20--%20%22%E6%AF%8F%E4%B8%80%E6%AD%A5%E9%83%BD%20%E2%89%BB%20y%22%20--%3E%20PASS%5B%22%E6%9E%81%E9%99%90%20x%20%E4%BB%8D%20%E2%89%BD%20y%EF%BC%9A%E9%80%9A%E8%BF%87%22%5D%0A%20%20Q%20--%20%22%E6%9E%81%E9%99%90%E7%AA%81%E7%84%B6%20%E2%89%BA%20y%22%20--%3E%20FAIL%5B%22%E5%81%8F%E5%A5%BD%E8%B7%B3%E5%B4%96%EF%BC%9A%E6%97%A0%E5%B7%AE%E5%BC%82%E5%B1%82%E6%96%AD%E8%A3%82%22%5D%0A%20%20LEX%5B%22%E8%AF%8D%E5%85%B8%E5%BA%8F%EF%BC%9A%E5%85%88%E6%AF%94%E7%AC%AC%201%20%E7%A7%8D%E5%95%86%E5%93%81%22%5D%20--%3E%20INF%5B%22%E4%B8%A4%E7%B1%BB%E5%95%86%E5%93%81%E6%9D%9F%E4%B9%8B%E9%97%B4%E9%9A%94%E7%9D%80%E6%97%A0%E7%A9%B7%E5%A4%9A%E5%B1%82%22%5D%0A%20%20INF%20--%3E%20NOU%5B%22%E6%B2%A1%E6%9C%89%E8%BF%9E%E7%BB%AD%E6%95%B0%E5%AD%97%E5%B0%BA%E5%AD%90%E8%83%BD%E7%BC%96%E5%8F%B7%22%5D%0A%20%20PASS%20--%3E%20U%5B%22%E8%BF%9E%E7%BB%AD%20u%20%E5%AD%98%E5%9C%A8%EF%BC%88Debreu%20%E8%A1%A8%E7%A4%BA%EF%BC%89%22%5D%0A%20%20FAIL%20--%3E%20NOU%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p><span class="marginnote">「序数效用」就是只报名次、不报分差：\\(u(x)=2\\)、\\(u(y)=1\\) 只说明 \\(x\\) 排在 \\(y\\) 前面，不说「好一倍」。把分数全体乘 100 或开根号，排名不变，所以它们表示同一套偏好——后课选哪个 \\(u\\) 纯看计算方便。</span></p><p><span class="marginnote">直觉类比：词典序像一本只看第一列的字典——先比第 1 种商品，多一丝就赢；一样多才轮到第 2 种。于是「第 1 种商品略少」的篮子，无论第 2 种多出多少，都被永远压在下面，层与层之间还塞着无穷多层。想给这些层编号，任何连续函数都会「挤爆」，这就是它没有连续表示的原因。</span></p><p><span class="marginnote">常见误区：把 \\(u(x)=2\\) 读成「\\(x\\) 带来的快乐是 \\(y\\) 的两倍」。表示定理只给排序，不给出基数；连「两个人的效用可以相加」都是福利理论另引的公理。也别把连续性读成「人的感觉是平滑的」——它是为了让微积分工具有处下手而付的建模代价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>表示定理不给出唯一 \\(u\\)，也不给出基数效用。期望效用课会再加独立性，那时仿射变换才被钉死——那是另一套公理，不是本课的加强。也不要把连续效用读成「人感觉平滑」：它是模型为了用分析工具付的拓扑代价。</p><p>实验里的不传递、不完备，上一课已经划成对照。本课在理性内部工作：若连续性也失败，后课的需求函数理论整段暂停。主干仍用 Debreu 表示，因为一般均衡的存在性证明要从连续需求出发。</p><p>拟凹、单调已经用来收紧需求形状，不是表示定理的前提。没有严格凸，\\(u\\) 仍可以存在，只是 \\(\\arg\\max\\) 可以是一整段无差异集。也不要把 Debreu 1954 的表示与 1959 年《价值理论》里的均衡存在混成一步：前者只把关系写成函数，后者才把函数送进市场。</p><p>后课默认：写 \\(u(x)\\) 就是在写一套连续理性偏好。预算、价格、收入，下一课才进入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限集上理性即有序数效用；\\(\\mathbb{R}_+^n\\) 上还要连续性，才有连续表示。</li><li>\\(u\\) 不是偏好的替代物，是表示；严格递增变换表示同一 \\(\\succsim\\)。</li><li>菜单上的选择改写成 \\(\\arg\\max u\\)；预算尚未出现。</li><li>单调与凸已经在先修课；本课不加可微。</li><li>词典序是理性但不连续的反例；主干不把它当消费者。</li><li>出处：Debreu, <em>Theory of Value</em>；Mas-Colell, Whinston and Green, <em>Microeconomic Theory</em> 第 3 章；Varian, <em>Microeconomic Analysis</em>。</li></ul>',10))])}const b=B(u,[["render",p]]);export{x as __pageData,b as default};
